  for (let value: int of values) {
    if (value >= 0) {
      counts[value] = counts[value] + 1 || 1;
    }
  }
  let bucketCounts: int[] = [];
  for (let i: int = 0; i < Math.ceil(Math.max.apply(null, values) / size); i = i + 1) {
    bucketCounts[i] = counts[i * size] || 0;
  }
  return bucketCounts;
}

