  let largestBucketCount: int = 0;
  for (let i: int = 0; i < Math.ceil(Math.max.apply(null, values) / size); i = i + 1) {
    let bucketCount: int = counts[i * size] || 0;
    if (bucketCount > largestBucketCount) {
      largestBucketIndex = i;
      largestBucketCount = bucketCount;
    }
  }
