export function bucketCounts(values: int[], size: int): int[] {
  if (size <= 0) {
    throw { code: "E_SIZE", message: "size must be positive" };
  }
  let buckets: int[] = new Array(Math.ceil(values.length / size)).fill(0);
  for (let value of values) {
    let index = Math.floor(value / size);
    buckets[index]++;
  }
  return buckets;
