export function largestBucket(values: int[], size: int): int {
  if (size <= 0) {
    throw { code: "E_SIZE", message: "size must be positive" };
  }
  let buckets: int[] = new Array(Math.ceil(values.length / size)).fill(0);
  for (let value of values) {
    let index = Math.floor(value / size);
    buckets[index]++;
  }
  let maxIndex = 0;
  for (let i = 1; i < buckets.length; i++) {
    if (buckets[i] > buckets[maxIndex]) {
      maxIndex = i;
    }
  }
  return maxIndex;
}

export function mode(values: int[]): int {
  if (values.length === 0) {
    return 0;
  }
  let counts: table = {};
  for (let value of values) {
    counts[value] = counts[value] ? counts[value] + 1 : 1;
  }
  let maxCount = 0;
  let modeValue = 0;
  for (let value in counts) {
    let count = counts[value];
    if (count > maxCount) {
      maxCount = count;
      modeValue = parseInt(value);
    }
  }
