import * as strings from "std/string";
import * as console from "std/console";

// @jsonable
export class Matrix {
  rows: int[][];
}

export function identity(n: int): Matrix {
  if (n <= 0) {
    return { rows: [] };
  }
  let matrix: Matrix = { rows: [] };
  for (let i: int = 0; i < n; i = i + 1) {
    let row: int[] = [];
    for (let j: int = 0; j < n; j = j + 1) {
      if (i === j) {
        row.push(1);
      } else {
        row.push(0);
      }
    }
    matrix.rows.push(row);
  }
  return matrix;
}

export function transpose(m: Matrix): Matrix {
  let transposed: Matrix = { rows: [] };
  for (let i: int = 0; i < m.rows.length; i = i + 1) {
    let row: int[] = [];
    for (let j: int = 0; j < m.rows[i].length; j = j + 1) {
      row.push(m.rows[j][i]);
    }
    transposed.rows.push(row);
  }
  return transposed;
}

export function rowSums(m: Matrix): int[] {
  let sums: int[] = [];
  for (let i: int = 0; i < m.rows.length; i = i + 1) {
    let sum: int = 0;
    for (let j: int = 0; j < m.rows[i].length; j = j + 1) {
      sum += m.rows[i][j];
    }
    sums.push(sum);
  }
  return sums;
}

export function trace(m: Matrix): int {
  let sum: int = 0;
  for (let i: int = 0; i < m.rows.length; i = i + 1) {
    sum += m.rows[i][i];
  }
  return sum;
}
