  let result: number = 0;
  for (let i: int = 0; i < coefficients.length; i = i + 1) {
    result = result + coefficients[i] * math.pow(x, i);
  }
  return result;
}

export function degree(coefficients: number[]): int {
  let degree: int = -1;
  for (let i: int = 0; i < coefficients.length; i = i + 1) {
    if (coefficients[i] !== 0) {
      degree = i;
    }
  }
  return degree;
}

export function derivative(coefficients: number[]): number[] {
  let derivative: number[] = [];
  for (let i: int = 1; i < coefficients.length; i = i + 1) {
    derivative[i - 1] = i * coefficients[i];
  }
  return derivative;
}

export function addPolys(a: number[], b: number[]): number[] {
  let result: number[] = [];
  let maxLength: int = Math.max(a.length, b.length);
  for (let i: int = 0; i < maxLength; i = i + 1) {
    let aVal: number = i < a.length && a[i] !== undefined
      || 0;
    let bVal: number = i < b.length && b[i] !== undefined
      || 0;
    result[i] = aVal + bVal;
  }
  return result;
