export function sortedCopy(values: int[]): int[] {
  let sorted: int[] = [];
  for (let i: int = 0; i < values.length; i = i + 1) {
    for (let j: int = i + 1; j < values.length; j = j + 1) {
      if (values[i] > values[j]) {
        let temp: int = values[i];
        values[i] = values[j];
        values[j] = temp;
      }
    }
  }
  return values;
}

export function isSorted(values: int[]): boolean {
  for (let i: int = 0; i < values.length - 1; i = i + 1) {
    if (values[i] > values[i + 1]) {
      return false;
    }
  }
  return true;
}

export function median(values: int[]): int {
  let sorted: int[] = sortedCopy(values);
  let count: int = sorted.length;
  if (count % 2 === 0) {
    return (sorted[count / 2 - 1] + sorted[count / 2]) / 2;
  } else {
    return sorted[count / 2];
  }
}

export function kthSmallest(values: int[], k: int): int | null {
  let sorted: int[] = sortedCopy(values);
  let count: int = sorted.length;
  if (k > count || k < 1) {
    return null;
  }
  let left: int = 0;
  let right: int = count - 1;
  while (left < right) {
    let pivotIndex: int = partition(sorted, left, right);
    if (pivotIndex === k - 1) {
      return sorted[pivotIndex];
    } else if (pivotIndex > k - 1) {
      right = pivotIndex - 1;
    } else {
      left = pivotIndex + 1;
    }
  }
  return sorted[left];
}

function partition(values: int[], left: int, right: int): int {
  let pivot: int = values[right];
  let i: int = left - 1;
  for (let j: int = left; j < right; j = j + 1) {
    if (values[j] <= pivot) {
      i = i + 1;
      let temp: int = values[i];
      values[i] = values[j];
      values[j] = temp;
    }
  }
  let temp: int = values[i + 1];
  values[i + 1] = values[right];
  values[right] = temp;
  return i + 1;
}

