import * as strings from "std/string";
import * as console from "std/console";

// @jsonable
export class Game {
  cells: string[] = Array(9).fill(" ");
  turn: string = "X";
}

export function newGame(): Game {
  return { cells: Array(9).fill(" "), turn: "X" };
}

export function place(game: Game, index: int): boolean {
  if (index < 0 || index >= 9 || game.cells[index] !== " ") {
    return false;
  }
  game.cells[index] = game.turn;
  game.turn = game.turn === "X" ? "O" : "X";
  return true;
}

export function lineWinner(game: Game, a: int, b: int, c: int): string | null {
  const mark = game.cells[a];
  if (mark === " ") {
    return null;
  }
  if (game.cells[b] === mark && game.cells[c] === mark) {
    return mark;
  }
  return null;
}

export function winnerOf(game: Game): string | null {
  for (let i = 0; i < 3; i++) {
    const mark = lineWinner(game, i * 3, i * 3 + 1, i * 3 + 2);
    if (mark) {
      return mark;
    }
    mark = lineWinner(game, i, i + 3, i + 6);
    if (mark) {
      return mark;
    }
  }
  const mark = lineWinner(game, 0, 4, 8);
  if (mark) {
    return mark;
  }
  return null;
}

export function isDraw(game: Game): boolean {
  return game.cells.every(cell => cell !== " ");
}

export function render(game: Game): string {
  return game.cells.map(cell => cell === " " ? " " : cell).join("\n|") + "\n";
}
