export class TrafficLight {
  state: string = "green";
}

export function isValid(state: string): boolean {
  return strings.equals(state, "green") || strings.equals(state, "yellow") || strings.equals(state, "red");
}

export function nextState(state: string): string {
  if (strings.equals(state, "green")) {
    return "yellow";
  } else if (strings.equals(state, "yellow")) {
    return "red";
  } else if (strings.equals(state, "red")) {
    return "green";
  } else {
    throw { code: "E_STATE", message: "invalid state" };
  }
}

export function after(state: string, steps: int): string {
  for (let i = 0; i < steps; i = i + 1) {
    state = nextState(state);
  }
  return state;
}

export function stepsTo(source: string, target: string): int {
  if (!isValid(source) || !isValid(target)) {
    return -1;
  }
  let current = source;
  let steps = 0;
  while (!strings.equals(current, target)) {
    current = nextState(current);
    steps = steps + 1;
  }
  return steps;
}

